sp_page.css:
body,
.sp-page-root,
.container,
.container-fluid{

background:
linear-gradient(
180deg,
#F3F6FB 0%,
#EDF2F8 100%
);

padding-top:0 !important;

}



/* PAGE ROWS */

.sp-row{

margin:0 !important;

padding:0 !important;

}



/* COLUMNS */

.sp-column{

padding-top:0 !important;

padding-bottom:0 !important;

margin-top:0 !important;

margin-bottom:10px !important;

}



/* WIDGETS */

.sp-widget{

margin-bottom:10px !important;

}



/* BOOTSTRAP */

.row{

margin-top:0 !important;

margin-bottom:0 !important;

}



/* HERO */

.directory-hero{

margin-bottom:10px !important;

}



/* FILTER */

.directory-filters{

margin-top:10px !important;

margin-bottom:10px !important;

}



/* GRID */

.directory-grid{

margin-top:0 !important;

}



/* REMOVE EXTRA BOTTOM SPACE */

.employee-card{

margin-bottom:0 !important;

}
